  'aud.dda_only': { en: 'Only the DDA level commits the season seed.', hi: 'सिर्फ़ DDA स्तर मौसम का बीज तय करता है।', pa: 'ਸਿਰਫ਼ DDA ਪੱਧਰ ਮੌਸਮ ਦਾ ਬੀਜ ਤੈਅ ਕਰਦਾ ਹੈ।' },
  'aud.rate': { en: 'Base rate', hi: 'मूल दर', pa: 'ਮੂਲ ਦਰ' },
